-- Marketing Launch modern ZIP quizzes. Safe to rerun.
-- Replaces only quiz questions and quiz titles; quiz attempts remain unchanged.
begin;
with course_row as (select id from courses where slug = 'marketing-launch')
insert into quizzes (course_id, quiz_key, title, passing_score, questions)
select course_row.id, 'quiz-1', 'اختبار الفصل 1: مقدمة إلى التسويق', 70, $json$[{"q":"التسويق يعني بشكل أساسي:","options":["الإعلان فقط","فهم السوق والعملاء وتقديم قيمة مناسبة لهم والتواصل معهم","بيع أي منتج لأي شخص","تصميم الشعار والألوان فقط"],"correctIndex":1},{"q":"الفرق بين التسويق والإعلان:","options":["لا فرق بينهما","الإعلان جزء من التسويق وليس كله","الإعلان أكبر من التسويق","التسويق يحدث بعد البيع فقط"],"correctIndex":1},{"q":"معادلة التسويق الأساسية تبدأ بـ:","options":["الإعلان","المشكلة ثم العميل","السعر","الشعار"],"correctIndex":1},{"q":"العميل يشتري بشكل أساسي:","options":["مواصفات المنتج فقط","الفائدة والنتيجة التي يحصل عليها","اسم الشركة فقط","لون المنتج فقط"],"correctIndex":1},{"q":"المسوّق الجيد يبدأ تفكيره من:","options":["المنتج الذي يريد بيعه","العميل ومشكلته","شكل الإعلان","عدد المتابعين"],"correctIndex":1},{"q":"هل التسويق يعني إقناع أي شخص بأي شيء؟","options":["نعم دائمًا","لا، التسويق الجيد يفهم الاحتياج ويقدم حلًا مناسبًا","نعم لأنه إعلان فقط","لا علاقة للتسويق بالثقة"],"correctIndex":1},{"q":"الفرق بين Feature وBenefit:","options":["لا فرق بينهما","Feature هي المواصفة، وBenefit هي الفائدة التي يحصل عليها العميل","Benefit هي السعر فقط","Feature أهم من Benefit دائمًا"],"correctIndex":1},{"q":"المبيعات (Sales) تركز بشكل أساسي على:","options":["دراسة السوق ككل","تحويل العميل المهتم إلى عميل يدفع فعليًا","تصميم الشعار","تحديد الميزانية السنوية"],"correctIndex":1},{"q":"التسويق جزء من:","options":["منظومة المشروع الكاملة مع المنتج والمبيعات والتشغيل","الإعلانات فقط بمعزل عن باقي المشروع","قسم منفصل تمامًا لا علاقة له بالمنتج","لا علاقة له بنجاح المشروع"],"correctIndex":0},{"q":"السؤال الجوهري الذي يجب أن يجيب عنه أي نشاط تسويقي:","options":["ما هو أفضل تصميم للإعلان؟","لماذا يختارني العميل بدلًا من المنافس؟","كم عدد المنشورات المطلوبة يوميًا؟","ما هو أرخص سعر ممكن؟"],"correctIndex":1}]$json$::jsonb
from course_row
on conflict (course_id, quiz_key) do update set title = excluded.title, passing_score = excluded.passing_score, questions = excluded.questions;

with course_row as (select id from courses where slug = 'marketing-launch')
insert into quizzes (course_id, quiz_key, title, passing_score, questions)
select course_row.id, 'quiz-2', 'اختبار الفصل 2: السوق والعميل', 70, $json$[{"q":"السوق (Market) يُعرَّف بأنه:","options":["مكان جغرافي فقط مثل المتجر","مجموعة العملاء المحتملين الذين لديهم حاجة أو مشكلة مشتركة","كل الناس في العالم","قائمة المنافسين فقط"],"correctIndex":1},{"q":"الترتيب الصحيح من الأوسع للأضيق هو:","options":["Niche → Segment → Market → Industry","Industry → Market → Segment → Niche","Market → Industry → Niche → Segment","لا يوجد ترتيب محدد"],"correctIndex":1},{"q":"لماذا لا يجب استهداف 'كل الناس'؟","options":["لأن هذا يجعل الرسالة أدق وأقوى","لأن الرسالة العامة نادرًا ما تجعل أحدًا يشعر أن المنتج مصمم له تحديدًا","لأن كل الناس متشابهون في احتياجاتهم","لأن التسويق لا يحتاج جمهورًا محددًا"],"correctIndex":1},{"q":"التقسيم النفسي (Psychographic) للسوق يهتم بـ:","options":["العمر والدخل فقط","الاهتمامات والقيم وأسلوب الحياة والمخاوف","الموقع الجغرافي فقط","لا علاقة له بالتسويق"],"correctIndex":1},{"q":"العميل المحتمل الحقيقي يحتاج توفر:","options":["الحاجة فقط بغض النظر عن أي شيء آخر","الحاجة والقدرة والرغبة والتوقيت والثقة معًا","المال فقط","معرفة اسم الشركة فقط"],"correctIndex":1},{"q":"المشكلة الظاهرة قد تختلف عن المشكلة الحقيقية، مثال ذلك:","options":["'عايز متابعين أكتر' قد تخفي مشكلة حقيقية هي ضعف الوصول للجمهور المناسب لجلب عملاء","كل المشاكل التي يذكرها العميل حقيقية دائمًا بنفس الشكل","لا يوجد فرق بين المشكلة الظاهرة والحقيقية أبدًا","المشكلة الحقيقية دائمًا هي السعر"],"correctIndex":0},{"q":"من طرق اكتشاف احتياجات العملاء:","options":["التخمين الشخصي فقط","المقابلات والاستبيانات ومراجعة التعليقات وبيانات المبيعات","تجاهل آراء العملاء تمامًا","نسخ استراتيجية منافس واحد فقط"],"correctIndex":1},{"q":"الهدف من تحليل المنافسين هو:","options":["نسخهم بالضبط","فهم السوق واكتشاف الفرص المتاحة","تجاهلهم تمامًا","خفض الأسعار فقط للمنافسة"],"correctIndex":1},{"q":"فجوة السوق (Market Gap) تعني:","options":["عدم وجود أي منافسين إطلاقًا في السوق","حاجة حقيقية لدى العملاء لا يتم تلبيتها بشكل جيد من المنافسين الحاليين","أن كل شيء في السوق مثالي بالفعل","لا علاقة لها بالفرص التجارية"],"correctIndex":1},{"q":"السؤال الأدق عند البحث عن عميل هو:","options":["مين يقدر يشتري منتجي؟","مين عنده مشكلة منتجي يقدر يحلها وبيدور فعلًا على حل ليها؟","مين أكبر عدد ممكن أستهدفه؟","مين عنده فلوس أكتر؟"],"correctIndex":1}]$json$::jsonb
from course_row
on conflict (course_id, quiz_key) do update set title = excluded.title, passing_score = excluded.passing_score, questions = excluded.questions;

with course_row as (select id from courses where slug = 'marketing-launch')
insert into quizzes (course_id, quiz_key, title, passing_score, questions)
select course_row.id, 'quiz-3', 'اختبار الفصل 3: شخصية العميل المثالي', 70, $json$[{"q":"شخصية العميل المثالي (Buyer Persona) هي:","options":["نموذج يمثل نوعًا محددًا من العملاء بناءً على معلومات حقيقية أو منطقية","اسم عشوائي بلا معنى","قائمة بكل العملاء الحاليين فقط","نفس الشيء تمامًا مثل السوق المستهدف العام"],"correctIndex":0},{"q":"الفرق بين العميل المستهدف (وصف عام) وشخصية العميل (Persona):","options":["لا فرق بينهما","الـPersona أكثر تفصيلًا وتشمل اسمًا وتفاصيل واقعية عن دوافعه ومخاوفه","العميل المستهدف أكثر تفصيلًا من الـPersona","كلاهما يعني نفس المعلومات الديموغرافية فقط"],"correctIndex":1},{"q":"يجب بناء شخصية العميل بالاعتماد على:","options":["الخيال الشخصي فقط بدون أي بيانات","بيانات حقيقية مثل المقابلات والاستبيانات وبيانات المبيعات","تخمين عشوائي لعمر ولون مفضل","نسخ شخصية منافس بالكامل"],"correctIndex":1},{"q":"لماذا شخصان بنفس العمر والدخل قد يحتاجان رسائل تسويقية مختلفة؟","options":["لأن بياناتهم النفسية (Psychographics) وأهدافهم قد تختلف تمامًا","هذا مستحيل الحدوث أبدًا","لأن العمر هو العامل الوحيد المهم","لا داعي للتفريق بينهما أبدًا"],"correctIndex":0},{"q":"الهدف الظاهر يختلف عن الهدف الحقيقي، مثال: 'عايز متابعين أكتر' قد يكون هدفها الحقيقي:","options":["زيادة الدخل وتكبير المشروع","لا علاقة له بأي هدف آخر","تغيير الشعار فقط","تقليل عدد المنافسين"],"correctIndex":0},{"q":"نقاط الألم (Pain Points) يجب فهمها من خلال:","options":["ذكر المشكلة فقط دون التعمق في تأثيرها","فهم كيف تؤثر المشكلة فعليًا على حياة أو عمل العميل","تجاهلها تمامًا عند بناء الرسالة","افتراض أنها نفسها لدى كل العملاء"],"correctIndex":1},{"q":"الاعتراضات الشائعة مثل 'السعر غالي' يجب أن:","options":["يتم تجاهلها تمامًا","تُعالَج بوضوح في الرسالة التسويقية قبل أن تمنع القرار","تكون سببًا لخفض السعر فورًا دائمًا","لا علاقة لها بقرار الشراء"],"correctIndex":1},{"q":"اختيار القناة المناسبة للتواصل مع العميل يعتمد على:","options":["أشهر منصة بشكل عام بغض النظر عن الجمهور","أين يقضي عميلك المستهدف وقته فعليًا","اختيار عشوائي لأي منصة","استخدام كل المنصات دائمًا بنفس الدرجة"],"correctIndex":1},{"q":"من الأخطاء الشائعة عند بناء شخصية العميل:","options":["التركيز على تفاصيل مهمة تؤثر على القرار","إضافة تفاصيل كثيرة غير مؤثرة على المشكلة أو القرار الشرائي","الاعتماد على بيانات حقيقية","تحديد أهدافه ومخاوفه بوضوح"],"correctIndex":1},{"q":"قد يكون لدى المشروع الواحد:","options":["شخصية عميل واحدة إلزاميًا دائمًا وبلا استثناء","أكثر من شخصية عميل إذا كانت هناك أنواع مختلفة من العملاء بمشكلات مختلفة","لا حاجة لبناء أي شخصية عميل إطلاقًا","شخصية عميل واحدة فقط تناسب كل نوع من المنتجات"],"correctIndex":1}]$json$::jsonb
from course_row
on conflict (course_id, quiz_key) do update set title = excluded.title, passing_score = excluded.passing_score, questions = excluded.questions;

with course_row as (select id from courses where slug = 'marketing-launch')
insert into quizzes (course_id, quiz_key, title, passing_score, questions)
select course_row.id, 'quiz-4', 'اختبار الفصل 4: رحلة العميل', 70, $json$[{"q":"رحلة العميل (Customer Journey) هي:","options":["لحظة الشراء فقط","المراحل التي يمر بها الشخص من اكتشاف المشكلة حتى يصبح عميلًا مستمرًا","الإعلان الأول الذي يراه العميل فقط","لا علاقة لها بمراحل متعددة"],"correctIndex":1},{"q":"المراحل السبعة لرحلة العميل تبدأ بـ:","options":["الشراء مباشرة","الوعي (Awareness) ثم الاهتمام فالتفكير والمقارنة","التوصية أولًا","الاحتفاظ بالعميل أولًا"],"correctIndex":1},{"q":"في مرحلة الوعي (Awareness)، يجب أن تكون الرسالة:","options":["طلب الشراء المباشر","لفت الانتباه للمشكلة، وليس البيع المباشر","معقدة وتقنية جدًا","خصمًا كبيرًا فورًا"],"correctIndex":1},{"q":"رحلة العميل تنتهي عند إتمام عملية الشراء:","options":["صحيح، الشراء هو نهاية الرحلة","خطأ، الشراء بداية مرحلة جديدة تشمل الاحتفاظ والتوصية","لا علاقة بين الشراء وبقية المراحل","المرحلة الوحيدة المهمة هي الشراء فقط"],"correctIndex":1},{"q":"مرحلة Advocacy (التوصية) تعني:","options":["أن العميل يشتري لأول مرة فقط","أن العميل راضٍ لدرجة أنه يوصي بالمنتج للآخرين","أن العميل توقف عن الشراء نهائيًا","لا علاقة لها برضا العميل"],"correctIndex":1},{"q":"رحلة العميل غالبًا:","options":["خط مستقيم دائمًا بدون أي تراجع","قد لا تكون خطًا مستقيمًا، وبعض الأشخاص يحتاجون وقتًا أطول من غيرهم","نفس المدة الزمنية لكل شخص دائمًا","تحدث دائمًا خلال ثوانٍ معدودة"],"correctIndex":1},{"q":"القمع التسويقي (Marketing Funnel) يوضح:","options":["أن كل من يشاهد المحتوى سيشتري حتمًا","أن عدد الأشخاص يقل تدريجيًا مع تقدمهم في مراحل الرحلة","أن عدد الأشخاص يزيد في كل مرحلة","لا علاقة له برحلة العميل"],"correctIndex":1},{"q":"خسارة بعض الأشخاص أثناء الرحلة تعتبر:","options":["كارثة يجب تجنبها دائمًا بأي ثمن","أمرًا طبيعيًا، والمهم هو وصول العدد المناسب من العملاء الملائمين","دليلًا على فشل المشروع بالكامل","غير وارد الحدوث أبدًا"],"correctIndex":1},{"q":"من أهم الأخطاء الشائعة في التعامل مع رحلة العميل:","options":["تخصيص رسالة مختلفة لكل مرحلة","استخدام نفس الرسالة لكل شخص بغض النظر عن مرحلته","بناء الثقة تدريجيًا","متابعة العميل بعد الشراء"],"correctIndex":1},{"q":"الثقة في رحلة العميل تُبنى من خلال:","options":["الوعود الكبيرة فقط بدون دليل","محتوى مفيد وشفافية وتقييمات ونتائج حقيقية بشكل تدريجي","تجاهل أسئلة العميل","الضغط المستمر للشراء الفوري"],"correctIndex":1}]$json$::jsonb
from course_row
on conflict (course_id, quiz_key) do update set title = excluded.title, passing_score = excluded.passing_score, questions = excluded.questions;

with course_row as (select id from courses where slug = 'marketing-launch')
