select course_row.id, 'quiz-5', 'اختبار الفصل 5: علم نفس التسويق', 70, $json$[{"q":"علم نفس التسويق يهتم بدراسة:","options":["الألوان فقط","كيف يفكر العميل ويشعر ويتخذ قراراته","أسعار المنافسين فقط","لا علاقة له بسلوك العميل"],"correctIndex":1},{"q":"العميل يشتري بشكل أساسي:","options":["المنتج فقط بمعزل عن أي شعور","القيمة والشعور الذي سيحصل عليه من استخدام المنتج","السعر الأرخص فقط دائمًا","الاسم التجاري فقط بغض النظر عن أي شيء آخر"],"correctIndex":1},{"q":"قرار الشراء غالبًا يبدأ بـ:","options":["منطق بحت بدون أي مشاعر","دافع عاطفي، ثم يتم تبريره بالمنطق","الصدفة البحتة فقط","لا علاقة للمشاعر بقرار الشراء إطلاقًا"],"correctIndex":1},{"q":"الدليل الاجتماعي (Social Proof) يعمل لأن:","options":["الناس تميل لمعرفة تجارب الآخرين قبل اتخاذ القرار","لا يوجد تأثير لآراء الآخرين إطلاقًا","الناس تتجاهل تقييمات الآخرين دائمًا","لا علاقة له بالثقة"],"correctIndex":0},{"q":"استخدام الندرة (Scarcity) والاستعجال (Urgency) يجب أن يكون:","options":["مزيفًا دائمًا لزيادة المبيعات بأي شكل","حقيقيًا، لأن الزيف يهدم الثقة عند اكتشافه","غير مهم إطلاقًا في التسويق","مستخدمًا في كل رسالة بلا استثناء"],"correctIndex":1},{"q":"السعر المرجعي (Price Anchoring) يعني:","options":["عرض سعر أعلى أولًا يجعل السعر الفعلي يبدو أكثر منطقية","تجاهل عرض أي سعر مرجعي","استخدام سعر واحد فقط بدون مقارنة","لا علاقة للسعر بعلم النفس"],"correctIndex":0},{"q":"الفرق بين المواصفة (Feature) والفائدة (Benefit):","options":["لا فرق بينهما","المواصفة تصف المنتج، والفائدة توضح ما يحصل عليه العميل فعليًا","الفائدة أقل أهمية من المواصفة دائمًا","المواصفة هي الشعور الذي يحصل عليه العميل"],"correctIndex":1},{"q":"تقليل المخاطرة (Risk Reduction) مثل الضمان يهدف إلى:","options":["تعقيد قرار الشراء أكثر","طمأنة العميل وتقليل خوفه من اتخاذ قرار خاطئ","رفع السعر بشكل غير مبرر","لا علاقة له بقرار الشراء"],"correctIndex":1},{"q":"التسويق الأخلاقي القائم على علم النفس يعني:","options":["استخدام الخوف المبالغ فيه والوعود الكاذبة لزيادة المبيعات","فهم مشاعر العميل الحقيقية ومساعدته على اتخاذ قرار مناسب دون تلاعب","تجاهل مشاعر العميل تمامًا","استخدام الندرة المزيفة دائمًا"],"correctIndex":1},{"q":"أهم قاعدة في علم نفس التسويق حسب الفصل هي:","options":["ابدأ بتصميم الإعلان أولًا قبل أي شيء آخر","افهم مشاعر العميل الحقيقية قبل التفكير في الرسالة أو الإعلان","ركّز على السعر فقط بغض النظر عن أي عامل آخر","تجاهل احتياجات العميل النفسية تمامًا"],"correctIndex":1}]$json$::jsonb
