with course_row as (select id from courses where slug = 'marketing-launch')
insert into quizzes (course_id, quiz_key, title, passing_score, questions)
select course_row.id, 'quiz-6', 'اختبار الفصل 6: أنواع التسويق', 70, $json$[{"q":"الفرق بين التسويق العضوي (Organic) والمدفوع (Paid):","options":["لا فرق بينهما","العضوي مجاني وبطيء لكنه يبني ثقة طويلة المدى، والمدفوع سريع لكنه يتوقف بإيقاف الميزانية","المدفوع دائمًا أفضل من العضوي بلا استثناء","العضوي يحتاج ميزانية أكبر من المدفوع"],"correctIndex":1},{"q":"تسويق المحتوى (Content Marketing) يقوم على فكرة:","options":["الطلب من العميل الشراء مباشرة في كل مرة","تقديم محتوى مفيد يجذب العميل ويبني ثقته أولًا","تجاهل احتياجات الجمهور تمامًا","نشر إعلانات مدفوعة فقط بدون أي محتوى مجاني"],"correctIndex":1},{"q":"اختيار منصة تواصل اجتماعي يجب أن يعتمد على:","options":["شهرة المنصة بشكل عام بغض النظر عن الجمهور","تواجد الجمهور المستهدف فعليًا في هذه المنصة","اختيار عشوائي لأي منصة","استخدام كل المنصات المتاحة دائمًا بنفس الدرجة"],"correctIndex":1},{"q":"نية البحث (Search Intent) تعني:","options":["عدد مرات البحث فقط","ما الذي يبحث عنه المستخدم فعليًا عندما يكتب كلمة بحث معينة","لا علاقة لها بمحركات البحث","اسم الموقع الذي يظهر أولًا في النتائج"],"correctIndex":1},{"q":"من مميزات التسويق عبر البريد الإلكتروني:","options":["أنه قناة تمتلكها أنت ولا تتأثر بتغييرات خوارزميات المنصات الأخرى","أنه أبطأ وسيلة تسويقية على الإطلاق بلا فائدة","أنه غير مناسب لبناء علاقة مستمرة مع العملاء","أنه لا يمكن قياس نتائجه إطلاقًا"],"correctIndex":0},{"q":"التسويق بالمؤثرين الصغار (Micro Influencers) مقارنة بالمؤثرين الكبار غالبًا:","options":["أعلى تكلفة دائمًا وبلا استثناء","أقرب لجمهورهم وأكثر ثقة، وتكلفته أقل عادة","لا فائدة منه إطلاقًا","له نفس الحجم الجماهيري بالضبط"],"correctIndex":1},{"q":"التسويق بالإحالة (Referral Marketing) قوي لأنه:","options":["مبني على ثقة حقيقية من عميل راضٍ يوصي بالمنتج لأصدقائه","لا يعتمد على أي ثقة سابقة","أضعف أنواع التسويق على الإطلاق","يتطلب ميزانية إعلانية ضخمة دائمًا"],"correctIndex":0},{"q":"هل يجب استخدام كل أنواع التسويق المتاحة في نفس الوقت؟","options":["نعم دائمًا لضمان أفضل نتيجة","لا، الأفضل التركيز على الأنواع الأنسب لعميلك وهدفك","لا فرق بين استخدام نوع واحد أو كل الأنواع","يجب استخدام نوع واحد فقط طوال الوقت بلا تغيير"],"correctIndex":1},{"q":"الفرق بين نوع التسويق والقناة:","options":["لا فرق بينهما، فإنستجرام مثلًا نوع من أنواع التسويق","القناة هي الوسيلة (مثل إنستجرام)، والنوع هو طبيعة المحتوى أو الأسلوب المستخدم فيها","النوع دائمًا أهم من القناة وبلا علاقة بينهما","القناة لا تؤثر أبدًا على اختيار نوع التسويق"],"correctIndex":1},{"q":"ربط أنواع التسويق برحلة العميل يعني:","options":["استخدام نفس النوع في كل مراحل الرحلة","اختيار النوع المناسب لكل مرحلة، مثل المحتوى في مرحلة الوعي والإعلانات المدفوعة في مرحلة القرار","تجاهل مراحل الرحلة تمامًا عند اختيار نوع التسويق","استخدام الإعلانات المدفوعة فقط في كل المراحل"],"correctIndex":1}]$json$::jsonb
from course_row
