with course_row as (select id from courses where slug = 'marketing-launch')
insert into quizzes (course_id, quiz_key, title, passing_score, questions)
select course_row.id, 'quiz-7', 'اختبار الفصل 7: أساسيات العلامة التجارية', 70, $json$[{"q":"العلامة التجارية (Brand) هي:","options":["الشعار فقط","الانطباع الكامل الذي يتكوّن لدى العميل عن المشروع من خلال كل تجربة معه","الألوان المستخدمة في التصميم فقط","اسم الشركة المسجل قانونيًا فقط"],"correctIndex":1},{"q":"الفرق بين المنتج (Product) والعلامة التجارية (Brand):","options":["لا فرق بينهما","المنتج هو ما تبيعه، والعلامة التجارية هي شعور الناس تجاهه واستعدادهم للدفع فيه","العلامة التجارية هي المنتج نفسه فقط","المنتج أهم من العلامة التجارية دائمًا وبلا استثناء"],"correctIndex":1},{"q":"الفرق بين الوعي (Awareness) والتذكر (Recall):","options":["لا فرق بينهما","الوعي هو معرفة وجودك، والتذكر هو أن يفكر فيك العميل أولًا عند الحاجة لحل","التذكر أقل أهمية من الوعي دائمًا","الوعي يعني أن العميل يشتري فورًا"],"correctIndex":1},{"q":"الهوية البصرية (الشعار والألوان والخطوط) تعتبر:","options":["العلامة التجارية بالكامل","أداة تدعم العلامة التجارية وليست العلامة التجارية نفسها","غير مهمة إطلاقًا في بناء العلامة التجارية","أهم عنصر ولا شيء غيرها يهم"],"correctIndex":1},{"q":"شخصية العلامة التجارية (Brand Personality) تُحدَّد بناءً على:","options":["رأي شخصي عشوائي بدون أي أساس","الجمهور المستهدف وقيم المشروع","تقليد شخصية أي منافس مشهور","لا علاقة لها بالجمهور المستهدف"],"correctIndex":1},{"q":"الاتساق (Consistency) في العلامة التجارية يعني:","options":["تغيير الهوية باستمرار لجذب الانتباه","الحفاظ على نفس الألوان والنبرة والقيم في كل مكان يظهر فيه المشروع","استخدام ألوان مختلفة في كل منصة","لا علاقة للاتساق بالثقة"],"correctIndex":1},{"q":"التموضع (Positioning) يختلف عن الميزة التنافسية (Competitive Advantage) في أن:","options":["لا فرق بينهما إطلاقًا","التموضع هو المكان الذي تريد امتلاكه في ذهن العميل، والميزة التنافسية هي ما يميزك فعليًا عن المنافسين","الميزة التنافسية أهم من التموضع دائمًا وبلا علاقة بينهما","التموضع لا علاقة له بالمنافسين إطلاقًا"],"correctIndex":1},{"q":"من الأخطاء الشائعة في بناء العلامة التجارية:","options":["التركيز على الشعار فقط وإهمال بقية عناصر العلامة","بناء قيم واضحة ومحددة","الحفاظ على اتساق الهوية عبر الوقت","تحديد شخصية واضحة للعلامة"],"correctIndex":0},{"q":"هل العلامة التجارية حكر على الشركات الكبيرة فقط؟","options":["نعم، المشاريع الصغيرة لا تحتاج علامة تجارية","لا، أي مشروع مهما كان صغيرًا يمكن ويجب أن يبني علامة تجارية واضحة","العلامة التجارية غير مهمة على الإطلاق للمشاريع الناشئة","فقط الشركات العالمية تحتاج علامة تجارية"],"correctIndex":1},{"q":"تجربة العميل (Customer Experience) ترتبط بالعلامة التجارية لأن:","options":["كل تفاعل مع العميل (خدمة، توصيل، رد) يبني أو يهدم الانطباع عن العلامة التجارية","لا علاقة بينهما إطلاقًا","تجربة العميل تخص المبيعات فقط وليس التسويق","العلامة التجارية تتعلق فقط بالإعلانات وليس الخدمة"],"correctIndex":0}]$json$::jsonb
