with course_row as (select id from courses where slug = 'marketing-launch')
insert into quizzes (course_id, quiz_key, title, passing_score, questions)
select course_row.id, 'quiz-8', 'اختبار الفصل 8: عرض القيمة', 70, $json$[{"q":"عرض القيمة (Value Proposition) هو:","options":["شعار جذاب فقط بدون معنى محدد","جملة أو فكرة توضح للعميل لماذا يختار منتجك تحديدًا وما الفائدة الحقيقية التي سيحصل عليها","قائمة أسعار المنتجات","اسم الشركة فقط"],"correctIndex":1},{"q":"التسلسل الصحيح من المنتج إلى القيمة هو:","options":["Value → Benefit → Feature → Product","Product → Feature → Benefit → Value","Feature → Product → Value → Benefit","لا يوجد تسلسل محدد بينهم"],"correctIndex":1},{"q":"الفرق بين عرض القيمة (Value Proposition) والشعار (Slogan):","options":["لا فرق بينهما إطلاقًا","عرض القيمة يوضح فائدة محددة وملموسة، بينما الشعار غالبًا جملة عامة وملهمة","الشعار دائمًا أكثر تحديدًا من عرض القيمة","كلاهما يجب أن يكون غامضًا لجذب انتباه أكبر عدد ممكن"],"correctIndex":1},{"q":"عرض القيمة القوي يجب أن يكون:","options":["مبالغًا فيه لجذب أكبر عدد من العملاء","واضحًا ومحددًا ومرتبطًا بنتيجة حقيقية ومختلفًا عن المنافسين","غامضًا بحيث يناسب الجميع","مطابقًا تمامًا لعرض قيمة المنافس الأقوى"],"correctIndex":1},{"q":"في لوحة عرض القيمة (Value Proposition Canvas)، 'Pain Relievers' تعني:","options":["الأشياء التي تزيد من مشاكل العميل","كيف يقلل منتجك من الإحباط أو المخاطرة أو الوقت الضائع لدى العميل","قائمة أسعار المنتج","لا علاقة لها بمشاكل العميل"],"correctIndex":1},{"q":"القيمة من وجهة نظر العميل لا تعني دائمًا:","options":["حل مشكلة حقيقية له","السعر الأقل فقط بالضرورة","توفير الوقت أو الجهد","الشعور بالثقة أو الراحة"],"correctIndex":1},{"q":"من الأخطاء الشائعة في كتابة عرض القيمة:","options":["التركيز على العميل ونتيجته","استخدام كلمات عامة لا تحدد شيئًا واضحًا، أو التركيز على الشركة بدلًا من العميل","ذكر فائدة محددة وواضحة","التميز عن المنافسين بوضوح"],"correctIndex":1},{"q":"اختبار قوة عرض القيمة يمكن أن يتم بسؤال:","options":["هل هو أطول جملة ممكنة؟","هل سيفهمه شخص غريب في ثوانٍ، وهل سيشعر أنه مختلف وقابل للتصديق؟","هل يحتوي على أكبر عدد من الكلمات الرنانة؟","هل يشبه شعار المنافس الأكبر تمامًا؟"],"correctIndex":1},{"q":"عرض القيمة يرتبط بالتموضع (Positioning) من خلال:","options":["لا علاقة بينهما إطلاقًا","التموضع هو المكان في ذهن العميل، وعرض القيمة هو الجملة التي توضح هذا المكان له","عرض القيمة يحل محل التموضع تمامًا","التموضع يُستخدم فقط بعد إتمام عملية البيع"],"correctIndex":1},{"q":"القاعدة الذهبية لعرض القيمة تقول:","options":["ركّز على وصف المنتج فقط بالتفصيل","وضّح النتيجة التي سيحصل عليها العميل، وليس فقط مواصفات المنتج","استخدم أكبر عدد من الكلمات التقنية الصعبة","لا داعي لذكر أي فائدة محددة للعميل"],"correctIndex":1}]$json$::jsonb
