select course_row.id, 'quiz-9', 'اختبار الفصل 9: الاستراتيجية التسويقية', 70, $json$[{"q":"الاستراتيجية التسويقية تبدأ دائمًا من:","options":["اختيار الإعلان المناسب أولًا","تحديد الهدف بوضوح","اختيار الألوان والتصميم","نسخ استراتيجية منافس ناجح"],"correctIndex":1},{"q":"الفرق بين Strategy وPlan وCampaign:","options":["لا فرق بينهم إطلاقًا","Strategy هي الاتجاه العام، Plan هي الخطوات التفصيلية، وCampaign هي تنفيذ محدد لهدف قصير المدى","Campaign أكبر من Strategy دائمًا","Plan لا علاقة له بالاستراتيجية"],"correctIndex":1},{"q":"تحليل SWOT يشمل:","options":["نقاط القوة والضعف والفرص والتهديدات","فقط نقاط القوة","فقط المنافسين","الميزانية فقط"],"correctIndex":0},{"q":"هدف SMART الجيد يكون:","options":["عامًا وغير محدد بأي رقم أو زمن","محددًا وقابلًا للقياس وواقعيًا ومرتبطًا بزمن محدد","بدون أي رقم يمكن قياسه","غير مرتبط بأي نتيجة تجارية"],"correctIndex":1},{"q":"Marketing Goal يجب أن يكون:","options":["منفصلًا تمامًا عن هدف البيزنس الأساسي","خادمًا لهدف البيزنس الأساسي (Business Goal)","أهم من هدف البيزنس دائمًا وبلا علاقة بينهما","غير قابل للقياس إطلاقًا"],"correctIndex":1},{"q":"اختيار القناة التسويقية المناسبة يعتمد على:","options":["شهرة القناة فقط بغض النظر عن الجمهور","وجود الجمهور المستهدف فعليًا في هذه القناة","استخدام كل القنوات المتاحة دائمًا بدون تركيز","اختيار عشوائي غير مرتبط بالهدف"],"correctIndex":1},{"q":"الاختبار (Testing) في الاستراتيجية التسويقية يهدف إلى:","options":["تجربة رسائل وأسعار مختلفة قبل التوسع في الإنفاق بثقة أكبر","تجنب أي تجربة والاعتماد على التخمين فقط","إنفاق كل الميزانية دفعة واحدة بدون اختبار","لا فائدة من الاختبار إطلاقًا"],"correctIndex":0},{"q":"هل يجب قياس كل المؤشرات (KPIs) بنفس الأهمية؟","options":["نعم، كل الأرقام لها نفس الأهمية دائمًا","لا، يجب التركيز على المؤشرات المرتبطة فعليًا بالهدف الأساسي","لا داعي لقياس أي شيء إطلاقًا","يكفي قياس عدد الإعجابات فقط"],"correctIndex":1},{"q":"من الأخطاء الشائعة في الاستراتيجية التسويقية:","options":["وجود هدف واضح ومحدد","استهداف جمهور محدد بدقة","اختيار القناة بسبب شهرتها فقط بدلًا من ملاءمتها للجمهور","اختبار الرسائل قبل التوسع فيها"],"correctIndex":2},{"q":"استراتيجية جيدة بدون تنفيذ جيد:","options":["كافية وحدها لتحقيق النجاح دائمًا","غالبًا لن تحقق النتائج المرجوة، فالاستراتيجية والتنفيذ يكملان بعضهما","لا علاقة لها بالتنفيذ إطلاقًا","أهم بكثير من التنفيذ بحيث لا يهم التنفيذ إطلاقًا"],"correctIndex":1}]$json$::jsonb
