insert into quizzes (course_id, quiz_key, title, passing_score, questions)
select course_row.id, 'quiz-10', 'اختبار الفصل 10: المحتوى التسويقي', 70, $json$[{"q":"المحتوى التسويقي (Marketing Content) يهدف بشكل أساسي إلى:","options":["البيع المباشر فقط في كل مرة","جذب انتباه الجمهور وبناء ثقته من خلال تقديم قيمة حقيقية","نشر أي محتوى عشوائي بدون هدف","الترويج للمنافسين"],"correctIndex":1},{"q":"الفرق بين المحتوى (Content) والإعلان (Ad):","options":["لا فرق بينهما","المحتوى يقدم قيمة ويبني علاقة، بينما الإعلان يطلب فعلًا محددًا بشكل مباشر","الإعلان دائمًا مجاني والمحتوى دائمًا مدفوع","المحتوى لا يمكن أن يكون له هدف تسويقي إطلاقًا"],"correctIndex":1},{"q":"أفضل مصدر لأفكار المحتوى هو:","options":["الخيال الشخصي البعيد عن الواقع فقط","فهم أسئلة العملاء الحقيقية واعتراضاتهم الشائعة ومشاكلهم","تقليد المنافسين حرفيًا فقط","النشر العشوائي بدون أي بحث"],"correctIndex":1},{"q":"الخطاف (Hook) في المحتوى مهم لأن:","options":["أول ثوانٍ من المحتوى تحدد استمرار الجمهور في المشاهدة أو القراءة","لا تأثير له على استمرار الجمهور","يجب أن يكون دائمًا مخادعًا (Clickbait)","غير ضروري في أي نوع من المحتوى"],"correctIndex":0},{"q":"الهيكل البسيط لكتابة محتوى جيد هو:","options":["CTA ثم Hook ثم Value","Hook ثم Value ثم CTA","Value فقط بدون أي مقدمة أو خاتمة","لا يوجد هيكل مفيد لكتابة المحتوى"],"correctIndex":1},{"q":"هل يجب أن يكون هدف كل قطعة محتوى هو البيع المباشر؟","options":["نعم دائمًا وبدون استثناء","لا، الإفراط في المحتوى البيعي فقط يجعل الجمهور يمل ويبتعد","المحتوى غير البيعي غير مفيد إطلاقًا","لا علاقة بين هدف المحتوى ونوعه"],"correctIndex":1},{"q":"إعادة استخدام المحتوى (Content Repurposing) تعني:","options":["إنشاء محتوى جديد من الصفر في كل مرة فقط","تحويل فكرة أساسية واحدة إلى عدة أشكال محتوى مختلفة","حذف كل المحتوى القديم دائمًا","نشر نفس المحتوى دون أي تعديل يناسب المنصة"],"correctIndex":1},{"q":"قياس أداء المحتوى يجب أن يختلف حسب:","options":["نوع المحتوى والهدف منه (وعي، تفاعل، أو تحويل)","لا يوجد أي اختلاف في طريقة القياس بين أنواع المحتوى","عدد الحروف في المنشور فقط","لون الخلفية المستخدمة في التصميم"],"correctIndex":0},{"q":"من الأخطاء الشائعة في المحتوى التسويقي:","options":["استخدام لغة تناسب العميل وفهم احتياجاته","النشر بدون هدف واضح والتركيز على الشركة بدلًا من العميل","قياس أداء المحتوى بانتظام","تنويع أشكال المحتوى حسب المنصة"],"correctIndex":1},{"q":"استراتيجية المحتوى (Content Strategy) الجيدة تتضمن:","options":["النشر العشوائي بدون تخطيط","تحديد الهدف والجمهور والأعمدة الأساسية للمحتوى ووتيرة النشر والقياس","الاعتماد فقط على المصادفة","نسخ محتوى المنافسين حرفيًا فقط"],"correctIndex":1}]$json$::jsonb
from course_row
on conflict (course_id, quiz_key) do update set title = excluded.title, passing_score = excluded.passing_score, questions = excluded.questions;

with course_row as (select id from courses where slug = 'marketing-launch')
insert into quizzes (course_id, quiz_key, title, passing_score, questions)
select course_row.id, 'quiz-11', 'اختبار الفصل 11: الحملة التسويقية', 70, $json$[{"q":"الحملة التسويقية (Marketing Campaign) هي:","options":["إعلان واحد منفرد بدون أي عناصر أخرى","مجموعة أنشطة منظمة تعمل معًا لتحقيق هدف محدد خلال فترة زمنية معينة","نفس الشيء تمامًا مثل الاستراتيجية طويلة المدى","منشور عشوائي على السوشيال ميديا"],"correctIndex":1},{"q":"أول خطوة أساسية عند بناء أي حملة هي:","options":["اختيار الألوان والتصميم","تحديد هدف واحد رئيسي وواضح للحملة","اختيار المؤثر المناسب مباشرة","تحديد الميزانية فقط بدون أي هدف"],"correctIndex":1},{"q":"الفرق بين الجمهور البارد (Cold) والساخن (Hot):","options":["لا فرق بينهما","الجمهور البارد لا يعرفك، بينما الساخن قريب جدًا من قرار الشراء","الجمهور الساخن هو الذي لا يعرفك على الإطلاق","كلاهما يحتاج نفس الرسالة بالضبط"],"correctIndex":1},{"q":"عرض الحملة (Campaign Offer) يهدف إلى:","options":["تعقيد قرار العميل قدر الإمكان","تسهيل اتخاذ القرار من خلال عرض واضح ومحدد","إخفاء تفاصيل المنتج عن العميل","لا علاقة له بزيادة التحويل"],"correctIndex":1},{"q":"الفرق بين Owned وPaid وEarned Media:","options":["لا فرق بينها إطلاقًا","Owned هي وسائطك الخاصة، Paid هي الإعلانات المدفوعة، وEarned هي التوصيات والمشاركات الطبيعية من الناس","كلها تعني نفس الشيء بالضبط","Paid Media هي الوحيدة المهمة في أي حملة"],"correctIndex":1},{"q":"أهمية الاتساق بين الإعلان وصفحة الهبوط تكمن في:","options":["عدم وجود أي داعٍ للاتساق بينهما","أن اختلاف الرسالة بينهما يربك العميل ويقلل الثقة والتحويل","أن يكون التصميم مختلفًا تمامًا لجذب الانتباه","لا علاقة للاتساق بمعدل التحويل"],"correctIndex":1},{"q":"إعادة الاستهداف (Retargeting) تُستخدم مع:","options":["أشخاص لم يسمعوا عن المشروع إطلاقًا","أشخاص تفاعلوا سابقًا مثل من زاروا صفحة الهبوط ولم يكملوا الشراء","المنافسين المباشرين فقط","لا فائدة منها في أي حملة"],"correctIndex":1},{"q":"استخدام أكثر من مادة إبداعية (Creative) في الحملة يساعد على:","options":["تشتيت الميزانية بدون أي فائدة","معرفة أي رسالة أو تصميم يحقق أفضل أداء من خلال المقارنة","إخفاء ضعف المنتج","لا علاقة له بتحسين الأداء"],"correctIndex":1},{"q":"الحكم على نجاح الحملة يجب أن يعتمد على:","options":["عدد المشاهدات فقط بغض النظر عن أي شيء آخر","مؤشرات مرتبطة بالهدف الفعلي مثل التحويل والتكلفة والربحية","الشكل الجمالي للإعلان فقط","عدد الإعجابات فقط"],"correctIndex":1},{"q":"القاعدة الذهبية للحملة الناجحة تجمع بين:","options":["هدف واضح وجمهور محدد وعرض قوي ورسالة متسقة وقياس مستمر","أكبر ميزانية ممكنة فقط بدون أي تخطيط","أشهر مؤثر فقط بدون أي استراتيجية","أكبر عدد من الإعلانات المختلفة بدون أي هدف محدد"],"correctIndex":0}]$json$::jsonb
from course_row
on conflict (course_id, quiz_key) do update set title = excluded.title, passing_score = excluded.passing_score, questions = excluded.questions;

with course_row as (select id from courses where slug = 'marketing-launch')
insert into quizzes (course_id, quiz_key, title, passing_score, questions)
select course_row.id, 'quiz-12', 'اختبار الفصل 12: القياس والتحسين', 70, $json$[{"q":"القياس التسويقي (Measurement) يهدف إلى:","options":["تجميع أكبر عدد من الأرقام بدون أي هدف","متابعة نتائج الجهود التسويقية لمعرفة ما ينجح وما يحتاج تعديلًا","تجاهل الأرقام والاعتماد على الحدس فقط","لا علاقة له بتحسين الأداء"],"correctIndex":1},{"q":"الفرق بين Measurement وAnalysis وOptimization:","options":["لا فرق بينهم إطلاقًا","Measurement يجمع الأرقام، Analysis يفهم معناها، وOptimization يعدّل بناءً عليها","Optimization يحدث قبل Measurement دائمًا","Analysis لا علاقة له بفهم الأرقام"],"correctIndex":1},{"q":"Vanity Metrics (المؤشرات الوهمية) تعني:","options":["أرقامًا مرتبطة مباشرة بالربحية دائمًا","أرقامًا قد تبدو جيدة لكنها لا ترتبط مباشرة بالنتيجة التجارية الحقيقية مثل الإعجابات وحدها","نفس معنى الـKPI الحقيقي تمامًا","أهم مؤشر يجب التركيز عليه دائمًا"],"correctIndex":1},{"q":"الفرق بين ROAS وROI:","options":["لا فرق بينهما إطلاقًا","ROAS يقيس العائد مقابل الإنفاق الإعلاني فقط، وROI يقيس العائد مقابل كل التكاليف","ROI يقيس الإعلانات فقط دون أي تكلفة أخرى","ROAS يشمل كل تكاليف الشركة"],"correctIndex":1},{"q":"إذا كان CTR منخفضًا، فالمشكلة غالبًا في:","options":["صفحة الهبوط فقط","الإعلان نفسه (الصورة أو النص أو الاستهداف)","المنتج فقط بغض النظر عن الإعلان","لا يمكن معرفة مصدر المشكلة أبدًا"],"correctIndex":1},{"q":"إذا كان CTR جيدًا لكن صفحة الهبوط لا تحوّل الزوار، فالمشكلة غالبًا في:","options":["صفحة الهبوط نفسها (الوضوح أو الثقة أو سهولة الاستخدام)","الإعلان الأساسي فقط","لا توجد أي مشكلة في هذه الحالة","الميزانية الإعلانية فقط"],"correctIndex":0},{"q":"القاعدة المهمة عند تحسين الحملات تقول:","options":["غيّر كل العناصر في نفس الوقت دائمًا لتسريع النتائج","لا تحاول تحسين كل شيء في نفس الوقت؛ غيّر عنصرًا واحدًا واختبره","لا داعي لاختبار أي تغيير قبل تطبيقه","التغيير العشوائي أفضل من الاختبار المنظم"],"correctIndex":1},{"q":"العلاقة بين CAC وLTV تساعد في معرفة:","options":["لا علاقة بينهما إطلاقًا","ما إذا كان بإمكانك استثمار المزيد في اكتساب عملاء جدد بأمان","لون التصميم الأنسب للإعلان","عدد الموظفين المطلوب في الفريق"],"correctIndex":1},{"q":"من الأخطاء الشائعة في القياس التسويقي:","options":["مقارنة النتائج عبر الوقت بانتظام","الحكم على الحملة بسرعة كبيرة قبل جمع بيانات كافية، أو الخلط بين الارتباط والسببية","تسجيل النتائج وتوثيقها","التركيز على الربحية الفعلية"],"correctIndex":1},{"q":"الخلاصة النهائية لمستوى Marketing Launch بأكمله تربط بين:","options":["فهم السوق والعميل فقط بمعزل عن أي شيء آخر","فهم السوق والعميل، وبناء استراتيجية ومحتوى وحملة، ثم القياس والتحسين المستمر","الإعلانات المدفوعة فقط دون أي استراتيجية","تصميم الشعار فقط باعتباره كافيًا للنجاح"],"correctIndex":1}]$json$::jsonb
from course_row
on conflict (course_id, quiz_key) do update set title = excluded.title, passing_score = excluded.passing_score, questions = excluded.questions;

